SELECT source_id, tenant_id, aggregate_type, aggregate_id, aggregate_version, payload_hash, payload_json::text,
    principal_id, membership_id, login_subject FROM auth_governance.directory_entry
WHERE source_id = #{source} AND aggregate_type = #{type} AND aggregate_id = #{id}

WITH RECURSIVE parents(id, depth, visited, cycle) AS (
    SELECT CAST(#{parent} AS varchar), 0, ARRAY[CAST(#{org} AS varchar)], #{parent} = #{org}
    UNION ALL
    SELECT e.payload_json->'organization'->>'parent_id', p.depth + 1, p.visited || p.id,
        (e.payload_json->'organization'->>'parent_id') = ANY(p.visited || p.id)
    FROM parents p JOIN auth_governance.directory_entry e ON e.source_id = #{source}
        AND e.aggregate_type = 'ORG' AND e.aggregate_id = p.id
    WHERE p.id IS NOT NULL AND NOT p.cycle AND p.depth < 64
) SELECT EXISTS (SELECT 1 FROM parents WHERE cycle OR depth >= 64)

SELECT  FROM auth_governance.directory_inbox
WHERE source_id = #{source} AND partition_sequence > #{start} AND partition_sequence < #{end}
ORDER BY partition_sequence LIMIT 10001

SELECT EXISTS (SELECT 1 FROM auth_governance.directory_inbox WHERE source_id = #{source} AND snapshot_id = #{id}
    AND (partition_sequence < #{start} OR partition_sequence > #{end}
        OR (aggregate_type IN ('EMPLOYEE','ORG') AND partition_sequence IN (#{start}, #{end}))))

